import{z as n,x as i,o as t,c as p,q as l,j as s,D as r,d as e,s as A,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"PFE 与 EE 敞口曲线","description":"","frontmatter":{"title":"PFE 与 EE 敞口曲线","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pfe-ee-profile.md","filePath":"quant/pfe-ee-profile.md","lastUpdated":1791413859000}'),d={name:"quant/pfe-ee-profile.md"};function C(m,E,D,F,P,u){const o=i("Mermaid");return t(),p("div",null,[E[2]||(E[2]=l('<h1 id="pfe-与-ee-敞口曲线" tabindex="-1">PFE 与 EE 敞口曲线 <a class="header-anchor" href="#pfe-与-ee-敞口曲线" aria-label="Permalink to &quot;PFE 与 EE 敞口曲线&quot;">​</a></h1><div class="epigraph"><p>对手方风险不在「现在欠多少」，而在「将来可能欠多少」——PFE 把这条未来敞口曲线画出来，监管资本与 CVA 都挂在上头。</p><footer>—— 据 Basel III SA-CCR 框架；Gregory《The xVA Challenge》</footer></div><p><a href="/quant/hazard-rate-model">风险率模型</a>给的是「对手方会不会违约」，本课补另一半：「违约时我们暴露多少」。净额结算与抵押品让敞口随市场漂移，缺口是<strong>敞口轮廓</strong>：期望敞口 EE、分位数敞口 PFE 随时间 \\(t\\) 的曲线。本课只做单笔与净额组合的敞口，不进 CVA 的定价离散化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一笔 10 年期利率互换今天市值为零，不等于对手方风险为零——利率上行后我方变成被欠方，敞口先升后降（「驼峰」）。监管要求按 **EEPE（有效期望敞口）**计资本，交易台需要 PFE 95% 曲线管理限额。缺口：<strong>从交易类型与市场波动推敞口曲线</strong>。本课不做错向抵押假设。</p><p><span class="marginnote">术语翻译：EE（Expected Exposure）= \\(t\\) 时刻敞口的期望；PFE（Potential Future Exposure）= 敞口的 \\(q\\) 分位数（常用 95%）；EEPE = 有效 EE 对时间加权平均，是 Basel 资本公式里的主角。</span></p><p><span class="marginnote">数字实例：1 亿美元名义、5 年期、利率互换年化波动 \\(\\sigma=1\\%\\)（绝对利率）。简化模型下 EE 峰值出现在约 \\(T/3\\) 处，量级 \\(\\approx 0.4\\,\\sigma\\sqrt{T/3}\\cdot N\\approx 0.4\\times1\\%\\times1.29\\times10^8\\approx 52\\) 万美元（名义的 0.5%）；PFE 95% 则是标准差项 \\(\\sigma\\sqrt{T/3}\\cdot N\\approx 129\\) 万美元再乘 1.645 倍分位因子，约 210 万美元。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>蒙特卡洛为主干：模拟风险因子路径（利率、汇率、信用利差）到每个再估值点；对每条路径、每个时点计算组合净现值，取正部（对手方违约只在我们被欠时伤到我们）；跨路径取期望得 EE、取分位数得 PFE。简化替代：SA-CCR 监管公式用名义、久期与乘数一步给出有效名义敞口，适合无算力场景。</p>',9)),(t(),s(B,null,{default:r(()=>[A(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%A3%8E%E9%99%A9%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20B%5B%22%E6%A8%A1%E6%8B%9F%20N%20%E6%9D%A1%E8%B7%AF%E5%BE%84%E8%87%B3%E5%90%84%E5%86%8D%E4%BC%B0%E5%80%BC%E7%82%B9%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%80%90%E7%82%B9%E7%BB%84%E5%90%88%E5%87%80%E7%8E%B0%E5%80%BC%20V%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%95%9E%E5%8F%A3%20%3D%20max(V%20-%20%E6%8A%B5%E6%8A%BC%2C%200)%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%B7%A8%E8%B7%AF%E5%BE%84%3A%20EE%3D%E5%9D%87%E5%80%BC%2C%20PFE%3D%E5%88%86%E4%BD%8D%22%5D%0A%20%20E%20--%3E%20F%5B%22EEPE%20%2F%20%E9%99%90%E9%A2%9D%20%2F%20CVA%20%E8%BE%93%E5%85%A5%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：EE 曲线像「每天平均欠款」，PFE 像「最倒霉的 5% 日子里欠多少」。互换的驼峰来自两个力：时间越长波动累积越狠（往上推），剩余期限越短未来波动折损越多（往下压）——先爬坡后下山。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("敞口曲线形状由「波动累积 vs 到期衰减」的赛跑决定：线性互换峰值在中间，期权类（买方）敞口单调升到期满，远期起始的驼峰右移。净额结算协议把同对手方正负市值相抵，抵押品把敞口从「市值」缩到「保证金变动期」（MPR，常 5–10 天）内的漂移——抵押越多，曲线整体被压得越低，但 MPR 段的尖峰仍在。"),a("em",null,"wrong-way risk"),e("（敞口与违约概率同向恶化，如对手方是石油商而敞口挂钩油价）让「EE × 违约概率」的乘法假设失真，CVA 要加相关项。")],-1)),(t(),s(B,null,{default:r(()=>[A(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%95%9E%E5%8F%A3%E5%BD%A2%E7%8A%B6%E7%94%B1%E8%B0%81%E5%AE%9A%3F%22%5D%20--%3E%7C%22%E6%B3%A2%E5%8A%A8%E7%B4%AF%E7%A7%AF%22%7C%20R%5B%22%E6%97%B6%E9%97%B4%E8%B6%8A%E9%95%BF%E8%B6%8A%E5%AE%BD%22%5D%0A%20%20Q%20--%3E%7C%22%E5%88%B0%E6%9C%9F%E8%A1%B0%E5%87%8F%22%7C%20S%5B%22%E4%B8%B4%E8%BF%91%E5%88%B0%E6%9C%9F%E5%BD%92%E9%9B%B6%22%5D%0A%20%20R%20--%3E%20T%5B%22%E7%BA%BF%E6%80%A7%E4%BA%92%E6%8D%A2%3A%20%E4%B8%AD%E6%AE%B5%E9%A9%BC%E5%B3%B0%22%5D%0A%20%20S%20--%3E%20T%0A%20%20U%7B%22%E6%9C%89%E6%8A%B5%E6%8A%BC%3F%22%7D%20--%3E%7C%22%E6%98%AF%22%7C%20V%5B%22%E6%95%9E%E5%8F%A3%E7%BC%A9%E8%87%B3%20MPR%20%E5%86%85%E6%BC%82%E7%A7%BB%22%5D%0A%20%20U%20--%3E%7C%22%E6%97%A0%22%7C%20W%5B%22%E5%85%A8%E9%A2%9D%20PFE%20%E5%85%A5%E9%99%90%E9%A2%9D%22%5D%0A%20%20V%20--%3E%20X%5B%22wrong-way%20%E4%BB%8D%E5%8F%AF%E8%83%BD%E5%87%BB%E7%A9%BF%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">常见误区：用名义当敞口——10 亿名义的平价互换当期敞口为零；另一个是忽略再估值点密度：三年后敞口高峰若落在两个再估值点之间会被系统性低估，月度网格对 30 年互换过粗，业界用期限分段的非均匀网格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒙特卡洛敞口机器的诚实成本是「因子模型 + 全组合再估值」两套系统的耦合，再估值贵时用代理函数（delta-gamma 近似）会在线性组合上失真。PFE 分位数对尾部模型敏感，正态假设低估 95% 分位——利率利差双跳时差 30% 不稀奇。监管口径（SA-CCR 的乘数与资产类别相关性）与内部模型口径不同，同笔交易两套数字都合法。CVA/VaR 的下游敏感性：EE 曲线错 10%，CVA 资本同幅偏移。</p><p><span class="marginnote">直觉类比：EE/PFE 像给对手方风险画「潮汐预报」——均值潮位（EE）安排日常，风暴潮位（PFE）决定堤坝（限额与抵押）；净额结算是先抽掉两船相抵的水位，抵押是临时沙袋，wrong-way 是风暴恰逢大潮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>敞口 = max(净市值 − 抵押， 0)；EE 是均值曲线，PFE 是分位曲线。</li><li>驼峰 = 波动累积与到期衰减的赛跑；期权买方单调升，互换中段峰。</li><li>SA-CCR 是监管捷径，蒙特卡洛是内部口径；wrong-way 让乘法假设失效。</li><li>出处：Basel III SA-CCR (2014)；Gregory《The xVA Challenge》第 4 版；Sorensen–Bollier 敞口定价 (1994)。</li></ul>',6))])}const g=n(d,[["render",C]]);export{h as __pageData,g as default};
